<script setup>import { clinicRoles } from '../../config/clinicRoles';import{reactive}from'vue';defineProps({open:Boolean});const emit=defineEmits(['close','save']);const form=reactive({name:'',email:'',password:'',password_confirmation:'',role:'staff'});function submit(){emit('save',{...form});form.password='';form.password_confirmation=''}</script><template><div v-if="open" class="modal-backdrop" @click.self="$emit('close')"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="member-title"><h2 id="member-title" class="text-xl font-bold">Add Member</h2><form class="mt-5 grid gap-4" @submit.prevent="submit"><label class="field">Name<input v-model="form.name" required></label><label class="field">Email<input v-model="form.email" type="email" required></label><label class="field">Password<input v-model="form.password" type="password" minlength="12" required></label><label class="field">Confirm password<input v-model="form.password_confirmation" type="password" required></label><label class="field">Role<select v-model="form.role"><option v-for="role in clinicRoles" :key="role">{{ role }}</option></select></label><div class="flex justify-end gap-3"><button type="button" class="btn-secondary" @click="$emit('close')">Cancel</button><button class="btn">Add Member</button></div></form></section></div></template>
